WITH ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY status, method ORDER BY amount DESC NULLS LAST, id) AS dedup_rank FROM payments QUALIFY dedup_rank = 1) SELECT CASE WHEN amount >= 1760 THEN 'PREMIUM' ELSE 'STANDARD' END AS amount_tier, APPROX_PERCENTILE(amount, 0.5) AS amount_p50, MAX(amount) FILTER (WHERE method = 'bank_transfer') AS bank_transfer_max_amount, COUNT(DISTINCT order_id) AS distinct_order_ids FROM ranked GROUP BY 1
